ulator = Map<\n  string,\n  { chartData: ChartBin[]; chartLabels: string[] }\n>;\n\nfunction initializeOrGetChartData(acc: ChartAccumulator, key: string) {\n  if (!acc.has(key)) {\n    acc.set(key, { chartData: [], chartLabels: [] });\n  }\n  return acc.get(key)!;\n}\n\nfunction createNumericScoreData(run: string, score: num"
