    expect(chartData[6]).toMatchObject({
      binLabel: "[0.86, 1]",
      count: 1,
    });
  });

  it("keeps integer-score binning unchanged", () => {
    expect(createHistogramData([{ value: 0 }, { value: 1 }], 2, 2)).toEqual({
      chartLabels: ["count"],
      chartData: [
        { binLabel: "[0, 0.5]", count: 1 },
        { binLabel: "[0.5, 1]", count: 1 },
      ],
    });
  });
});

