              "text": "[Document context]\nTitle: Langfuse count-weighted pivot rollup fix\nSource: Langfuse issue #15208 candidate\nPath: /code/langfuse/web/src/features/widgets/utils/pivot-table-utils.ts\nWorkspace: task/sana-farid/langfuse-15208-weighted\n\ncount: numericValue(row[countMetric]),\n    }))\n    .filter(\n      (row): row is { value: number; count: number } =>\n        row.value !== undefined && row.count !== undefined,\n    );\n  const totalCount = weightedRows.reduce((sum, row) => sum + row.count, 0);\n\nreturn totalCount === 0\n    ? 0\n    : weightedRows.reduce((sum, row) => sum + row.value * row.count, 0) /\n        totalCount;\n}\n\n/**\n * Calculates subtotals for a group of data rows\n * Aggregates metric values across all rows in the group using the correct aggregation function\n *\n * @param data - Array of database rows to calculate subtotals for\n * @param metrics - Array of metric field names to aggregate\n * @returns Object with metric names as keys and calculated totals as values\n */\nexport function calculateSubtotals(\n  data: DatabaseRow[],\n  metrics: string[],\n): Record<string, number> {\n  const subtotals: Record<string, number> = {};\n  const countMetric = metrics.find(\n    (metric) => metric === \"count\" || detectAggregationType(metric) === \"count\",\n  );\n\nfor (const metric of metrics) {\n    // Extract all values for this metric using the utility function\n    const values = data\n      .map((row) => extractMetricValues(row, [metric])[metric])\n      .filter(isNotNullOrUndefined);\n\n// Detect aggregation type and apply correct function\n    const aggregationType = detectAggregationType(metric);\n    const result =\n      aggregationType === \"avg\"\n        ? calculateAverage(data, metric, countMetric, values)\n        : applyAggregation(values, aggregationType);\n\n// Round to 10 decimal places to avoid floating-point precision issues\n    subtotals[metric] = Math.round(result * 1e10) / 1e10;\n  }\n\nreturn subtotals;\n}",
