        validatePivotTableConfig(configWithNoDimensions),
      ).not.toThrow();
      expect(() =>
        validatePivotTableConfig(configWithOneDimension),
      ).not.toThrow();
      expect(() =>
        validatePivotTableConfig(configWithTwoDimensions),
      ).not.toThrow();
    });

