              "text": "[Document context]\nTitle: Langfuse count-weighted pivot rollup fix\nSource: Langfuse issue #15208 candidate\nPath: /code/langfuse/web/src/features/widgets/utils/pivot-table-utils.ts\nWorkspace: task/sana-farid/langfuse-15208-weighted\n\n*/\nfunction applyAggregation(values: number[], aggregationType: string): number {\n  if (values.length === 0) return 0;\n\nswitch (aggregationType) {\n    case \"count\":\n    case \"sum\":\n      return values.reduce((sum, val) => sum + val, 0);\n\ncase \"avg\":\n      return values.reduce((sum, val) => sum + val, 0) / values.length;\n\ncase \"min\":\n      return Math.min(...values);\n\ncase \"max\":\n      return Math.max(...values);\n\ncase \"percentile\":\n      // For percentiles in subtotals/totals, we'll use the average of the percentile values\n      // This is a reasonable approximation since we can't recalculate the true percentile\n      return values.reduce((sum, val) => sum + val, 0) / values.length;\n\ndefault:\n      // Default to sum\n      return values.reduce((sum, val) => sum + val, 0);\n  }\n}\n\nfunction numericValue(value: DatabaseRow[string]): number | undefined {\n  if (typeof value === \"number\") return value;\n  if (typeof value !== \"string\") return undefined;\n\nconst parsedValue = Number.parseFloat(value);\n  return Number.isNaN(parsedValue) ? undefined : parsedValue;\n}\n\n/**\n * Recombines group averages using their row counts. If the query does not\n * include a count metric, callers retain the previous unweighted fallback.\n */\nfunction calculateAverage(\n  data: DatabaseRow[],\n  metric: string,\n  countMetric: string | undefined,\n  values: number[],\n): number {\n  if (!countMetric) return applyAggregation(values, \"avg\");\n\nconst weightedRows = data\n    .map((row) => ({\n      value: numericValue(row[metric]),\n      count: numericValue(row[countMetric]),\n    }))\n    .filter(\n      (row): row is { value: number; count: number } =>\n        row.value !== undefined && row.count !== undefined,\n    );\n  const totalCount = weightedRows.reduce((sum, row) => sum + row.count, 0);",
